(window.TNQ=window.TNQ||[]).push({"terms":{"구성개념":{"d":"직접 관찰할 수 없고 이론과 가설로 정의되어, 관련된 행동을 통해 간접적으로 측정하는 심리적 개념이다.","r":[]},"조작적 정의":{"d":"추상적 개념을 관찰하고 측정할 수 있는 구체적 절차나 행동으로 정의하는 것이다.","r":[]},"요인분석":{"d":"여러 변수의 상관 구조를 분석해 공통 요인을 추출하는 통계 기법으로 구인타당도 검증에 쓰인다.","r":[]},"규준표":{"d":"표집 자료로 작성한 점수 해석용 표로, 원점수를 규준 점수로 환산한다.","r":[]},"연령규준":{"d":"같은 연령 집단의 수행을 기준으로 개인 점수를 해석하는 규준이다.","r":[]},"일반요인":{"d":"스피어만이 모든 지적 과제에 공통으로 작용한다고 본 지능의 g요인이다.","r":[]},"유동지능":{"d":"새로운 문제를 풀 때 쓰이는 추론과 적응 능력으로 카텔과 호른이 제시한 개념입니다.","r":["결정지능"]},"결정지능":{"d":"교육과 경험을 통해 쌓은 지식과 언어 능력에 바탕을 둔 지능입니다.","r":["유동지능"]},"자유연상검사":{"d":"떠오르는 생각을 제한 없이 말하게 하여 사고를 파악하는 방법으로, 문장완성검사의 모태가 되었다.","r":[]},"단어연상검사":{"d":"자극 단어를 제시하고 떠오르는 단어로 응답하게 하는 검사이다.","r":[]},"행동표본":{"d":"전체 행동 중에서 대표로 추출해 측정한 일부 행동이다. 심리검사는 이를 표준 절차로 측정한다.","r":[]},"투사적 검사":{"d":"모호한 자극에 대한 자유로운 반응에서 무의식적 욕구와 내적 갈등을 파악하는 검사이다. 채점과 해석이 어렵다.","r":[]},"객관적 검사":{"d":"문항과 응답 방식이 정해져 있어 채점과 해석이 객관적인 자기보고식 검사이다.","r":[]},"준거참조검사":{"d":"개인을 집단과 비교하지 않고 정해진 기준이나 범주에 따라 합격과 불합격 등으로 분류하는 검사이다.","r":[]},"능력검사":{"d":"수검자에게 최대한 능력을 발휘하게 하는 검사로 정답이 있으며, 지능검사, 신경심리검사, 적성검사가 해당한다.","r":[]},"성향검사":{"d":"성격, 흥미, 태도처럼 개인의 습관적 경향을 측정하는 검사이다.","r":[]},"스테나인":{"d":"점수를 1에서 9까지의 아홉 범주로 나누는 표준점수이다.","r":[]},"등간척도":{"d":"단위 간격이 같고 절대영점이 없는 척도로 선형변환이 가능하다.","r":[]},"비율척도":{"d":"절대영점이 있고 간격이 같아 비율 비교가 가능한 척도이다.","r":[]},"서열척도":{"d":"대상의 순서만 나타내며 간격은 같다고 볼 수 없는 척도이다.","r":[]},"명명척도":{"d":"대상을 공통 속성에 따라 범주로 나누어 이름을 붙이는 척도이다.","r":[]},"절대영점":{"d":"측정하는 속성이 전혀 없음을 뜻하는 기준 0점으로, 비율척도에만 있다.","r":[]},"누적평정법":{"d":"리커트가 제안한 척도 구성법으로, 문항 응답 점수를 합산해 총점을 구한다.","r":[]},"등현간격법":{"d":"써스톤이 제안한 척도 구성법으로, 문항의 척도값을 판단자들이 정하고 수검자는 선택한 문항 척도값의 중앙치로 점수를 받는다.","r":[]},"양극형용사":{"d":"의미가 반대인 형용사 쌍 사이에서 위치를 골라 응답하는 방식에 쓰이는 형용사이다.","r":[]},"검사-재검사 신뢰도":{"d":"같은 검사를 같은 사람에게 시간 간격을 두고 두 번 실시하여 점수 상관으로 구하는 신뢰도로, 안정성계수라고도 한다.","r":[]},"동형검사신뢰도":{"d":"동등한 두 검사 형태를 같은 사람에게 실시해 점수 상관으로 구하는 신뢰도로, 검사-재검사의 연습 효과를 줄인다.","r":[]},"반분신뢰도":{"d":"한 검사를 반으로 나누어 두 부분 점수의 상관으로 구하는 신뢰도이다.","r":[]},"관찰자간 신뢰도":{"d":"같은 행동을 관찰한 여러 관찰자의 기록이 일치하는 정도이다.","r":[]},"안정성계수":{"d":"검사-재검사 신뢰도 계수로, 시간 경과에 따른 점수의 안정성을 나타낸다.","r":[]},"짝진 임의 배치법":{"d":"문항을 비슷한 것끼리 짝지어 임의로 두 집단에 배정하는 반분 방식이다.","r":[]},"연습 효과":{"d":"같은 검사를 반복하면 익숙해져 점수가 오르는 현상이다.","r":[]},"내용타당도":{"d":"문항들이 측정하려는 영역을 얼마나 대표하는지를 전문가가 판단해 확인하는 타당도이다.","r":[]},"안면타당도":{"d":"검사가 겉보기에 측정하려는 것을 재는 것처럼 보이는 정도로, 수검자 입장에서 판단된다.","r":[]},"구인타당도":{"d":"검사가 측정하려는 이론적 구성개념을 실제로 측정하는 정도이며 요인분석으로 검증할 수 있다.","r":[]},"수렴타당도":{"d":"같은 구성개념을 재는 다른 검사와 점수가 높게 관련되는 정도이다.","r":[]},"예언타당도":{"d":"검사 점수가 미래의 준거를 얼마나 잘 예측하는지를 보는 준거타당도의 하나이다.","r":[]},"공인타당도":{"d":"같은 시점에서 이미 타당성이 확인된 다른 검사와의 상관으로 확인하는 준거타당도이다.","r":[]},"준거타당도":{"d":"검사 점수와 외부 준거의 관계로 확인하는 타당도로 예언타당도와 공인타당도가 있다.","r":[]},"문항변별도":{"d":"문항이 점수가 높은 집단과 낮은 집단을 구별하는 정도이다.","r":[]},"문항난이도":{"d":"문항에 정답을 한 사람의 비율로 문항의 쉽고 어려운 정도를 나타낸다.","r":[]},"문항특성곡선":{"d":"능력 수준에 따른 문항 정답 확률의 변화를 나타내는 곡선이다.","r":[]},"문항반응이론":{"d":"수검자의 능력과 문항 특성으로 정답 확률을 설명하는 검사 이론으로 문항곤란도, 문항변별도, 추측정답 가능성을 모수로 쓴다.","r":[]},"진위형 문항":{"d":"진술이 맞는지 틀리는지를 고르게 하는 문항이다.","r":[]},"예비검사":{"d":"본 검사 개발 전에 모집단을 대표하는 대상에게 문항을 시험적으로 실시하는 검사이다.","r":[]},"백분위":{"d":"집단에서 해당 점수 이하를 받은 사람의 비율을 나타낸 값이다.","r":[]},"편차 IQ":{"d":"같은 연령 집단 내 상대적 위치를 평균과 표준편차로 나타낸 지능지수이다.","r":[]},"환산점수":{"d":"소검사 원점수를 평균과 표준편차가 정해진 표준점수로 바꾼 점수이다.","r":[]},"처리점수":{"d":"웩슬러 소검사 수행 과정에서 얻는 보조적 점수로, 다른 소검사 점수로 대체할 수 없다.","r":[]},"결정성 지능":{"d":"카텔이 구분한 지능으로 학습과 경험을 통해 축적되며 언어와 지식에 기반한다.","r":[]},"특수요인":{"d":"스피어만이 특정 과제에만 작용한다고 본 지능 요인이다.","r":[]},"기본적인 정신능력":{"d":"써스톤이 제시한 지능의 다요인설로, 언어, 수, 공간, 기억 등 서로 독립적인 정신능력으로 구성된다고 본다.","r":[]},"3차원 모델":{"d":"길포드가 내용, 조작, 결과 세 차원으로 지능의 구조를 설명한 모델이다.","r":[]},"다중지능이론":{"d":"가드너가 지능을 언어, 논리수학, 개인내 지능 등 여러 독립적 지능으로 설명한 이론이다.","r":[]},"성공지능":{"d":"스턴버그가 분석적, 창의적, 실제적 능력으로 구성된다고 본 지능이다.","r":[]},"Gf-Gc 이론":{"d":"카텔과 호른이 지능을 유동지능과 결정지능으로 구분한 이론이다.","r":[]},"CHC":{"d":"카텔, 호른, 캐롤의 이론을 통합한 모델로 지능을 일반지능, 넓은 인지능력, 좁은 인지기능의 층위로 설명한다.","r":[]},"인지효율성 지표":{"d":"웩슬러 검사에서 작업기억과 처리속도의 합산으로 산출되는 보조 지표이다.","r":[]},"지각추론지수":{"d":"비언어적 추론과 시각 정보 처리 능력을 나타내는 웩슬러 검사의 지수이다.","r":[]},"지우기":{"d":"제한시간 내에 배열된 도형들에서 표적 자극과 같은 도형을 찾아 표시하는 처리속도 소검사이다.","r":[]},"순서화":{"d":"일련의 숫자와 문자를 듣고 순서대로 재배열하는 작업기억 소검사이다.","r":[]},"공통성":{"d":"두 단어나 그림의 유사점을 설명하는 언어 개념 소검사이다.","r":[]},"숫자폭 검사":{"d":"불러 준 숫자를 순서대로 또는 거꾸로 회상하는 주의력과 단기기억 검사이다.","r":[]},"연속수행검사":{"d":"일정 시간 자극을 보며 표적에만 반응하게 하여 지속적 주의력을 측정하는 검사이다.","r":[]},"BGT-2":{"d":"벤더 게슈탈트 검사 2판으로 아동과 성인에게 실시하며 지각-운동 기능을 평가한다.","r":[]},"단순화":{"d":"BGT 채점에서 도형의 형태가 단순하게 바뀌는 일탈이다.","r":[]},"폐쇄 곤란":{"d":"BGT에서 도형의 닫힌 부분을 닫지 못하거나 연결하지 못하는 오류이다.","r":[]},"MMPI-A":{"d":"청소년용으로 개발된 MMPI로, 성인용에 없는 내용척도와 보충척도를 포함한다.","r":[]},"보충척도":{"d":"MMPI-2 기본 척도 외에 특정 특성이나 증후군을 평가하는 추가 척도이다.","r":[]},"재구성 임상척도":{"d":"MMPI-2 임상척도를 요인으로 재구성한 RC 척도이다.","r":[]},"코드 유형":{"d":"MMPI-2에서 가장 높은 임상척도 조합으로 해석하는 유형이다.","r":[]},"자아강도":{"d":"스트레스에 대처하고 심리적으로 적응하는 자아의 힘으로, MMPI-2 ES 척도가 반영한다.","r":[]},"MBTI":{"d":"융의 유형론에 근거해 외향-내향, 감각-직관, 사고-감정, 판단-인식의 선호를 측정하는 검사이다.","r":[]},"선호지표":{"d":"MBTI에서 정보를 인식하고 판단하는 방식의 선호 경향을 나타내는 지표이다.","r":[]},"치료척도":{"d":"PAI에서 공격성, 자살관념, 스트레스, 비지지, 치료거부 등 치료 계획에 필요한 정보를 주는 척도이다.","r":[]},"기질척도":{"d":"TCI에서 자극추구, 위험회피, 사회적 민감성, 인내력을 측정하는 척도이다.","r":[]},"NEO-PI-R":{"d":"5요인 성격이론에 따라 신경증, 외향성, 개방성, 호감성, 성실성을 측정하는 검사이다.","r":[]},"홀랜드":{"d":"직업적 성격을 현실적, 탐구적, 예술적, 사회적, 기업적, 관습적 유형으로 구분한 진로 이론을 제안한 학자이다.","r":[]},"일관성":{"d":"홀랜드 이론에서 개인의 성격 유형들이 서로 얼마나 비슷한지를 나타낸다.","r":[]},"일치성":{"d":"홀랜드 이론에서 성격 유형과 직업환경 유형이 얼마나 유사한지를 나타낸다.","r":[]},"단어연상 검사":{"d":"자극 단어에 떠오르는 단어로 반응하게 하는 검사로, 문장완성검사의 모태가 되었다.","r":[]},"HTP검사":{"d":"집, 나무, 사람을 그리게 하여 성격과 정서를 해석하는 투사적 그림 검사이다.","r":[]},"TAT":{"d":"그림 카드로 이야기를 만들게 해 욕구와 환경 압력, 갈등을 파악하는 주제통각검사이다.","r":[]},"문장완성검사":{"d":"미완성 문장을 수검자가 떠오르는 대로 완성하게 하여 성격과 갈등, 태도를 파악하는 투사검사이다.","r":[]},"주제통각검사":{"d":"그림 카드를 보고 이야기를 만들게 해 내적 욕구와 환경적 압력, 대인관계 역동을 파악하는 투사검사이다.","r":[]},"백지카드":{"d":"TAT에서 그림이 없는 카드로, 수검자가 장면을 상상해 이야기를 만든다.","r":[]},"자기개념":{"d":"자신의 능력, 특성, 가치에 대해 갖는 생각으로, 삭스의 문장완성검사 대표 영역의 하나이다.","r":[]},"로샤":{"d":"잉크반점에 대한 반응으로 지각, 사고, 정서를 평가하는 대표적 투사검사이다.","r":[]},"조직점수":{"d":"로샤 종합체계에서 자극을 의미 있게 조직하여 반응한 정도를 나타내는 Z점수이다.","r":[]},"형태질":{"d":"로샤 종합체계에서 반응이 반점의 모양과 얼마나 잘 맞는지를 나타내는 채점이다.","r":[]},"반응 영역":{"d":"로샤에서 수검자가 반응한 반점의 부위로 W, D, Dd, S 기호로 표시한다.","r":[]},"결정인":{"d":"로샤에서 수검자의 반응을 일으킨 반점의 특성으로, 형태, 색채, 운동, 음영 등이 있다.","r":[]},"강박성향지표":{"d":"로샤 종합체계에서 강박적 성격 경향을 확인하는 지표로 OBS라고 한다.","r":[]},"발달질":{"d":"로샤 종합체계에서 반응의 형태 구체성과 조직화 정도를 구분하는 채점 기호이다.","r":[]},"종합체계":{"d":"엑스너가 로샤 채점과 해석을 통합하여 경험적으로 체계화한 방식이다.","r":[]},"표본":{"d":"전집에서 추출한 일부 집단이다.","r":[]},"전집":{"d":"연구에서 관심을 두는 전체 대상의 집합으로 모집단이라고도 한다.","r":[]},"모수치":{"d":"전집의 수량적 특성을 나타내는 값이다.","r":[]},"최빈치":{"d":"분포에서 가장 빈도가 높은 점수이다.","r":[]},"변산도":{"d":"점수가 흩어진 정도로 표준편차와 분산으로 나타낸다.","r":[]},"분산":{"d":"표준편차를 제곱한 값으로, 점수가 평균에서 흩어진 정도를 나타낸다.","r":[]},"비모수통계":{"d":"모집단의 분포가 정상분포를 따른다는 가정 없이 사용하는 통계 방법이다.","r":[]},"유층표집":{"d":"전집을 여러 하위집단으로 나눈 뒤 각 하위집단에서 비율을 고려해 무선으로 뽑는 표집 방법이다.","r":[]},"무선표집":{"d":"모든 대상이 같은 확률로 뽑히도록 무작위로 표본을 추출하는 방법이다.","r":[]},"리커트 척도":{"d":"문항에 대한 동의 정도를 단계별로 응답하게 하는 평정 척도이다.","r":[]},"상관계수":{"d":"두 변인이 함께 변하는 정도와 방향을 나타내는 값이다. 제곱하면 한 변인의 분산이 다른 변인으로 설명되는 비율이 된다.","r":[]},"정규분포":{"d":"평균을 중심으로 좌우 대칭인 종 모양 분포로 평균, 중앙값, 최빈값이 일치한다.","r":[]},"부적 편포":{"d":"분포의 꼬리가 왼쪽으로 길어 높은 점수에 사례가 몰리는 분포이다.","r":[]},"작업동맹":{"d":"상담이나 평가에서 수검자와 전문가가 목표를 공유하며 협력하는 관계로, 감정적 유대를 포함한다.","r":[]},"라포":{"d":"수검자와 검사자 사이의 신뢰와 친밀한 관계로, 수검자가 협조하는 분위기의 바탕이 된다.","r":[]},"사전 동의":{"d":"검사의 목적과 절차를 충분히 설명한 뒤 수검자에게 받는 자발적 동의이다.","r":[]},"비밀보장":{"d":"검사에서 얻은 정보를 수검자 동의 없이 공개하지 않는 윤리 원칙이다.","r":[]},"이중관계":{"d":"검사자와 수검자가 전문적 관계 외에 사적이거나 다른 관계를 함께 맺는 것으로, 객관성을 해칠 수 있어 피해야 한다.","r":[]},"낙인":{"d":"검사 결과로 개인에게 부정적 꼬리표가 붙는 일이다.","r":[]},"평가 불안":{"d":"검사 상황에서 평가받는다는 생각으로 생기는 불안이다.","r":[]},"검사 매뉴얼":{"d":"검사의 실시, 채점, 해석 방법을 정리한 지침서이다.","r":[]},"법적 대리인":{"d":"동의 능력이 없는 수검자를 대신해 법적으로 동의할 권한이 있는 사람이다.","r":[]}},"notes":{"‘가족, 성(이성), 대인관계, 자기개념’의 네 가지 영역으로 구분":"삭스의 문장완성검사는 문항을 네 가지 생활 영역으로 나눠 태도를 살핍니다.","“마음 내키는 대로 그리세요.”라고 대답":"그리는 방식에 정해진 답이 없다는 점을 알려 주어 수검자의 자유로운 표현을 막지 않습니다.","“전신 그림을 그리세요.”라고 지시":"신체 일부만 그렸다면 온몸을 그리라고 지시해 사람 전체의 모습을 얻습니다.","각 문장을 읽고 즉각적으로, 제일 먼저 떠오르는 것을 완성":"오래 고민하면 꾸며 쓰게 되므로 처음 떠오른 생각을 바로 적게 합니다.","개인의 대표적인 행동표본을 심리학적 방법으로 측정":"심리검사는 사람의 행동 전체가 아니라 대표가 될 만한 일부 행동을 체계적으로 재는 일입니다.","개인의 특성을 이해하는 데 도움을 줄 수 있음":"검사는 사람의 특성을 이해하는 보조 수단일 뿐 결론을 대신 내려 주지는 않습니다.","개인정보는 사용이 제한되고 지정된 목적을 위해 사용되어야 함":"수검자의 정보는 처음 밝힌 목적 안에서만 쓰고 그 밖의 용도로 쓰면 안 됩니다.","객관적 검사와 투사적 검사로 구분":"성격검사는 선택지를 고르는 객관적 검사와 모호한 자극에 반응하는 투사적 검사로 나뉩니다.","검사가 필요한 이유를 설명하고 수검자의 사전 동의를 얻음":"검사를 하는 목적을 알려 주고 수검자가 납득해서 허락한 뒤에 실시합니다.","검사 개발의 목적에 따라 검사 개발 절차와 내용이 결정":"무엇을 위해 만드는 검사인지에 맞게 문항 구성과 개발 순서가 정해집니다.","검사결과가 한 개인을 낙인찍지 않도록 주의를 기울여야 함":"진단 결과가 한 사람을 고정된 부정적 꼬리표로 규정하지 않게 신중히 전달해야 합니다.","검사를 시행하는 시간간격의 영향을 받음":"같은 검사를 두 번 실시하는 사이의 시간이 점수 일치도에 영향을 줍니다.","검사자의 숙련도는 검사결과에 영향을 줌":"실시와 채점, 해석을 얼마나 능숙하게 하는지에 따라 결과가 달라질 수 있습니다.","검사재료를 안전하게 보관하고 자격 없는 사람이 접근하지 못하도록 함":"검사 문항과 도구가 유출되면 타당성이 무너지므로 자격이 있는 사람만 다루게 합니다.","검증을 위해 요인분석을 사용할 수 있음":"문항들이 이론대로 묶이는지 요인분석으로 확인하면 구인타당도를 검증할 수 있습니다.","과도한 걱정이나 긴장을 평가":"Pt 척도는 지나친 걱정과 긴장, 불안정한 사고를 살피는 척도입니다.","구성개념에 대한 측정은 간접적인 방법을 이용 · 조작적 정의를 통해 구성개념과 관련된 행동의 일부를 측정":"개념을 관찰 가능한 행동으로 정의한 뒤 그 행동의 일부를 재서 개념을 간접적으로 측정합니다.","그리는 방법에 관해 질문하는 경우":"HTP 검사 중 수검자가 어떻게 그려야 하는지 물을 때의 대응을 설명하는 앞부분입니다.","기억력과 문제해결능력 등을 평가":"인지척도는 영유아가 기억하고 문제를 푸는 능력의 발달을 살핍니다.","길수록 신뢰도가 낮아질 수 있음":"재검사 간격이 길면 그 사이에 수검자의 상태가 변해 점수가 달라지기 쉽습니다.","네 가지 차원을 기본 축으로 구성":"MBTI는 선호를 네 쌍의 반대되는 축으로 나누어 성격 유형을 정합니다.","다른 소검사 점수로 대체할 수 없음":"처리점수는 수행 과정을 보는 보조 정보여서 소검사 점수를 대신해 합산할 수 없습니다.","다양한 신체증상 정도를 평가":"HEA 척도는 건강 문제와 몸의 여러 증상을 얼마나 호소하는지 보여 줍니다.","단어연상 검사의 변형으로 발전":"제시어에 단어로 답하던 방식을 문장 전체로 넓혀 변형한 검사입니다.","대상은 그 검사를 실제 사용할 모집단의 성격을 잘 대표할 수 있도록 구성":"예비검사 대상이 실제 검사 대상과 다르면 문항 분석 결과를 믿기 어려워서 비슷하게 뽑습니다.","대표적인 투사적 검사로 로샤검사와 주제통각검사":"잉크 반점을 보고 말하는 로샤와 그림을 보고 이야기를 만드는 주제통각검사가 투사검사의 예입니다.","동일한 대상에게 여러 가지 유사한 개념들을 사용할 경우, 수검자들이 과제에 흥미를 잃고 지루해할 수 있음":"비슷한 형용사 쌍을 거듭 평가하게 하면 집중이 떨어져 성의 없는 응답이 늘어납니다.","동일한 대상자의 다른 특성에 대해서는 평가와 의미부여가 달라 일관성이 없는 경우가 많음":"한 사람이 특성마다 다른 기준으로 평가해서 응답에 일관성이 떨어지기 쉽습니다.","똑같은 형용사 쌍이라도 수검자들의 개별적인 경험에 따라 각기 다른 의미로 인식될 수 있음":"좋다와 나쁘다 같은 낱말도 사람마다 떠올리는 경험이 달라 같은 점수가 같은 뜻이 아닙니다.","만 6세 0개월에서 16세 11개월까지의 아동과 청소년에게 실시":"K-WISC-V가 실시되는 연령 범위로, 초등학교 입학 무렵부터 청소년기까지입니다.","매우 이상한 사고와 경험을 보고":"A-biz 척도가 높으면 현실과 동떨어진 기이한 생각과 경험을 많이 보고합니다.","모든 문항은 오직 하나의 잠재적 특성만을 측정해야 함":"한 문항이 여러 특성을 동시에 재면 점수 해석이 흐려지므로 단일 특성만 측정해야 합니다.","모든 인간이 공통적으로 갖고 있는 일반(g)요인을 주장":"사람이라면 누구에게나 있는 공통된 지능 요인이 있다고 본 것이 스피어만 이론의 핵심입니다.","모집단의 확률분포가 정상분포를 따르지 않을 때 사용하는 방법":"자료가 정규분포라는 가정을 세울 수 없을 때 쓰는 통계 방법입니다.","문장에 따라 모호함의 정도가 다름":"어떤 문항은 의도가 뻔하고 어떤 문항은 열려 있어 투사의 정도가 문항마다 다릅니다.","문장의 전반적인 흐름과 미묘한 뉘앙스를 통해":"해석은 개별 단어보다 문장 전체의 분위기와 결을 읽는 데서 출발한다는 문장의 앞부분입니다.","문항들이 측정하고자 하는 영역을 얼마나 대표하는지를 말함":"문항이 재려는 내용 영역 전체를 골고루 담았는지의 정도로, 내용타당도의 핵심입니다.","문항의 적절성 판단은 주로 수검자의 평가로 이루어짐":"안면타당도는 전문가가 아니라 검사를 받는 사람이 보기에 적절한지를 기준으로 합니다.","미완성 문장을 수검자가 자기 생각대로 완성하도록 하는 검사":"문장완성검사는 시작만 주어진 문장을 수검자가 자기 말로 이어서 끝내게 하는 투사 검사입니다.","반추 및 의사결정 곤란 정도를 평가":"OBS 척도는 같은 생각을 되풀이하고 결정을 내리기 어려워하는 정도를 봅니다.","분포 내에서 가장 빈도가 높은 점수":"자료에서 가장 여러 번 나온 값으로, 최빈치는 평균이나 중앙값과 다른 대푯값입니다.","사람 그림에서 처음에 신체 일부만 그리는 경우":"사람 그림을 얼굴이나 상반신 일부로 끝냈을 때의 대응을 설명하는 앞부분입니다.","사실적 정보에 대한 지식을 평가하는 데 유용":"맞고 틀림이 분명한 사실을 얼마나 아는지 확인하는 데 알맞은 문항 형식입니다.","산출하려면 두 명 이상의 평가자가 필요":"평가자 간 신뢰도는 서로 다른 평가자의 점수가 일치하는 정도여서 평가자가 둘 이상이어야 구합니다.","상승은 자신을 완벽하고 이상적으로 가장하려는 경향성을 나타냄":"L척도가 높으면 자신을 실제보다 도덕적이고 흠 없는 사람으로 보이게 하려는 응답을 뜻합니다.","상호 간에 감정적으로 친밀하게 느끼는 인간관계":"검사자와 수검자 사이에 서로 편안하고 가깝다고 느끼는 관계를 라포라고 합니다.","생후 1개월부터 42개월 영유아를 대상으로 함":"이 검사는 아주 어린 아기부터 만 세 살 반 무렵까지의 영유아에게 실시합니다.","소검사 환산점수 10과 동일한 상대적 위치":"소검사 환산점수 10은 평균에 해당하는 위치이며 지표점수에서도 같은 위치가 있습니다.","소근육과 대근육 운동수준 등을 평가":"손가락을 쓰는 작은 움직임과 걷기 같은 큰 움직임의 발달 정도를 확인합니다.","수검자가 협력적인 태도를 갖도록 동기를 유발하는 우호적 분위기":"따뜻한 분위기에서 수검자는 검사에 성실히 임하고 협조하려는 마음이 생깁니다.","수검자에게 종이를 세로로 제시":"나무 그림은 위아래로 긴 형태여서 종이를 세로 방향으로 줍니다.","수검자에 대한 치료전략을 제시":"검사 결과로 수검자에게 맞는 개입 방향을 정하는 근거를 마련할 수 있습니다.","수검자의 권리를 보호해야 함":"검사자는 수검자의 사생활과 자기결정 같은 권리가 침해되지 않도록 지켜야 합니다.","수검자의 능력 수준은 능력을 측정하기 위해 사용하는 문항에 따라 달라지지 않아야 함":"어떤 문항으로 재든 같은 사람의 능력 추정치는 같아야 한다는 가정입니다.","수검자의 성격 패턴을 도출할 수 있음":"응답을 종합하면 수검자가 반복해서 보이는 성격의 경향을 알아낼 수 있습니다.","순위는 정할 수 있으나 서열의 크기와 정도는 비교할 수 없음":"리커트 척도의 점수는 순서만 의미하고 칸 사이의 간격이 같다고 보기 어렵습니다.","신뢰도는 검사문항 수의 영향을 받음":"문항 수가 늘면 우연한 오차가 서로 상쇄되어 신뢰도가 높아지는 경향이 있습니다.","신뢰도는 문항들의 난이도의 영향을 받음":"문항이 너무 쉽거나 어려우면 점수 차이가 줄어 신뢰도가 낮아질 수 있습니다.","신뢰도는 사례 수의 영향을 받음":"표본의 사례가 많을수록 신뢰도 추정치가 안정됩니다.","신뢰도에 영향을 미칠 수 있음":"수검자가 검사에 얼마나 열심인가에 따라 점수가 흔들려 신뢰도가 영향을 받습니다.","심리검사를 정확하게 실시하고 해석하기 위한 훈련이 필요":"검사를 다루는 사람은 실시와 해석에 필요한 전문적 수련을 받아야 합니다.","심리검사에서 불필요한 정보를 담고 있지 않음":"좋은 문항은 재려는 특성과 관련 없는 요소가 섞이지 않아 점수의 의미가 분명합니다.","심리적 구성개념은 이론적이고 가설적인 개념":"지능이나 불안은 이론에서 가정한 개념이어서 실물처럼 볼 수 없습니다.","심리적 구성개념을 측정하는 도구":"눈에 보이지 않는 지능이나 성격 같은 이론적 개념을 숫자로 나타내는 데 쓰는 도구입니다.","심리적 구성개념을 측정하는 방법은 다양할 수 있음":"같은 개념도 설문, 면접, 관찰, 투사검사 등 여러 방법으로 잴 수 있습니다.","심리적 속성은 직접적으로 측정할 수 없음":"마음의 특성은 키처럼 바로 잴 수 없고 드러난 행동으로 짐작해야 합니다.","심리적 특성에 대한 개인간 차이 또는 개인내 차이를 확인하는 방법":"사람들 사이의 차이와 한 사람 안에서 영역별 강약의 차이를 가려내는 방법입니다.","아동을 대상으로 개인검사를 실시할 때 필수적":"아동은 낯선 상황에서 쉽게 위축되므로 친밀감을 쌓아야 제 능력을 발휘합니다.","언어 이해, 시공간 기능, 유동 추론, 작업 기억, 처리 속도의 5개 지표점수로 구성":"다섯 영역의 지표 점수로 아동의 인지 능력을 영역별로 나누어 보여 줍니다.","언어 이해, 지각 추론, 작업 기억, 처리 속도의 4개 지표 점수로 구성":"이전 판인 K-WISC-IV는 지표가 네 가지이고 지각 추론이 한 지표로 묶여 있었습니다.","에너지를 얻는 근원에 관한 설명":"E와 I의 구분은 힘을 바깥 세계에서 얻는지 내면에서 얻는지에 대한 것입니다.","연구자가 관심을 가지는 연구대상의 속성":"변인은 연구 대상에게서 달라지는 특성 가운데 연구자가 관심을 두는 것입니다.","연령규준을 설정할 때 성인보다 아동의 경우 연(월) 간격을 좁게 함":"아동은 짧은 기간에도 능력이 크게 자라서 규준 집단의 나이 간격을 촘촘히 잡습니다.","올바른 활용을 위해 기능과 용도를 정확하게 알아야 함":"검사마다 재는 대상과 쓰임이 달라서 잘못 쓰면 결과를 오해하게 됩니다.","요인분석을 통해 ‘내용, 조작 및 결과’ 차원의 3차원 모델을 제시":"길포드는 지능을 내용, 조작, 결과를 축으로 하는 입체 구조로 설명했습니다.","우울 증상을 측정하는 임상척도":"MMPI의 D척도는 의욕 저하와 비관 같은 우울 증상 수준을 재는 임상척도입니다.","유동지능과 결정지능의 Gf-Gc 이론을 제안":"카텔과 호른은 지능을 새로운 문제를 푸는 유동지능과 경험으로 쌓은 결정지능으로 구분했습니다.","이상반응 경향성을 탐지하기 위한 척도":"F척도는 일반인에게 드문 문항에 많이 답했는지 보아 비정상적이거나 과장된 응답을 가려냅니다.","인지 및 행동 등 발달 수준을 평가하는 데 사용":"발달검사는 영유아가 인지와 행동 면에서 또래 수준에 있는지 살핍니다.","일반 지능(g요인)의 개념을 가정":"스피어만은 여러 지적 활동에 공통으로 작용하는 하나의 일반 지능이 있다고 가정했습니다.","일반화된 불안 및 걱정을 평가":"ANX 척도는 특정 대상에 한정되지 않은 전반적인 불안을 평가합니다.","자아강도를 나타내는 보충척도":"MMPI에서 ES척도는 심리적 어려움을 이겨 내는 자아의 힘을 가늠하는 보충 척도입니다.","자유롭고 풍부한 반응을 하는 것이 가능":"정해진 답이 없는 자극이어서 수검자가 자기 방식대로 폭넓게 반응할 수 있습니다.","자유연상검사와 단어연상검사 등으로부터 발전":"문장완성검사는 자유연상검사와 단어연상검사 같은 연상 기법에서 나왔습니다.","전집을 여러 개의 하위집단으로 나눈 후 하위 집단 내에서의 비율을 고려하여 무선표집하는 방법":"전체를 층으로 나누고 각 층의 비율대로 무작위로 뽑아 표본이 모집단의 구성을 닮게 합니다.","전체 지능지수 85와 소검사 환산점수 7":"웩슬러 척도에서 지능지수 85와 소검사 환산점수 7이 같은 상대적 위치를 나타냅니다.","전체 지능지수 95와 동일한 상대적 위치":"지표점수 95는 집단 안에서 전체 지능지수 95와 같은 위치를 뜻합니다.","정보를 수집하는 방법에 관한 설명":"S와 N의 구분은 정보를 현실의 구체적 사실로 받아들이는지 의미와 가능성으로 받아들이는지에 대한 것입니다.","제한시간 내에 조직적으로 배열되어 있는 도형들 속에서 표적 자극과 동일한 도형을 찾아 표시함":"정해진 시간 안에 줄지어 놓인 그림 중 같은 모양을 빨리 찾아 표시하는 처리속도 과제입니다.","지각추론지수가 시각공간 지수와 유동추론 지수로 분리":"이전 판의 지각추론 지수가 새 판에서는 시공간과 유동추론 두 지수로 갈렸습니다.","지능의 구조를 3차원 모델로 구성":"지능의 구성 요소를 세 방향의 축으로 조합해 나타낸 모델입니다.","지능의 다요인설인 기본적인 정신능력(PMA)을 주장":"써스톤은 지능을 하나가 아니라 서로 독립적인 여러 기본 능력으로 나누어 보았습니다.","지능이 일반요인과 특수요인의 2요인으로 구성":"지능은 모든 과제에 쓰이는 일반요인과 특정 과제에만 쓰이는 특수요인 둘로 이루어진다는 설명입니다.","짧을수록 연습 효과와 기억 효과가 발생할 가능성이 커짐":"간격이 짧으면 처음 풀었던 문제를 기억하거나 익숙해져서 점수가 달라질 수 있습니다.","토막짜기 소검사는 시공간 기능 지표에 포함":"토막짜기는 모양을 눈으로 분석해 구성하는 과제여서 시공간 기능 지표에 들어갑니다.","통제력 및 성급함 정도를 평가":"ANG 척도는 화를 참는 힘과 성급함이 어느 정도인지 나타냅니다.","투사적 검사로 보기 어렵다는 견해도 있음":"문항 의도가 비교적 분명해 응답을 꾸밀 수 있어서 순수한 투사검사가 아니라고 보는 시각도 있습니다.","특정 문항에 대한 반응은 다른 문항에 대한 반응에 영향을 미치지 않아야 함":"문항 사이의 영향이 없어야 각 문항을 따로 분석할 수 있다는 국소독립의 가정입니다.","평가 의뢰인과 수검자가 동일하지 않은 경우, 평가서나 의뢰보고서는 의뢰인의 동의가 전제 되어야 수검자에게 열람될 수 있음":"의뢰한 사람이 따로 있으면 그 사람의 허락이 있어야 수검자가 보고서를 볼 수 있습니다.","표본의 특성에 따라 달라지지 않아야 함":"문항의 난이도와 변별력 같은 특성은 어떤 집단에 실시해도 같아야 합니다.","표집에서 얻은 자료를 토대로 규준표를 작성":"표집 집단의 점수 분포를 정리해 원점수를 상대적 위치로 바꾸는 규준표를 만듭니다.","하나의 심리검사 결과만으로 개인을 판단해서는 안 됨":"검사 한 가지로는 오류 가능성이 있어서 면담과 행동 관찰 등 다른 자료와 함께 봐야 합니다.","핵심소검사가 숫자와 그림폭으로 구성":"새 판의 작업기억 지표 기본 소검사는 숫자와 그림폭 두 가지입니다.","형용사 쌍이 중복된다고 판단될 경우 나중 반응은 별 의미가 없을 수 있음":"앞에서 이미 답한 것과 같다고 느끼면 뒤의 응답은 새로운 정보를 주지 못합니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
